<script setup lang="ts">
definePageMeta({ layout: false })
const route = useRoute(); const config = useRuntimeConfig(); const email = ref(''); const password = ref(''); const confirmation = ref(''); const loading = ref(false); const message = ref(''); const error = ref(''); const token = computed(() => String(route.query.token || '')); const apiBase = computed(() => String(config.public.apiBase || '').replace(/\/$/, ''))
const submit = async () => { error.value = ''; message.value = ''; if (token.value && password.value !== confirmation.value) { error.value = 'As senhas nao conferem.'; return }; loading.value = true; try { if (token.value) { await $fetch(`${apiBase.value}/api/auth/password-reset/confirm`, { method: 'POST', body: { token: token.value, newPassword: password.value } }); message.value = 'Senha redefinida. Agora voce ja pode entrar.' } else { await $fetch(`${apiBase.value}/api/auth/password-reset/request`, { method: 'POST', body: { email: email.value } }); message.value = 'Se o e-mail estiver cadastrado, voce recebera as instrucoes.' } } catch (cause: any) { error.value = cause?.data?.error || cause?.message || 'Nao foi possivel processar a solicitacao.' } finally { loading.value = false } }
</script>
<template><main class="auth-page"><section class="auth-panel"><div class="auth-brand"><AppLogo /><p>Recupere seu acesso com seguranca.</p></div><form class="auth-form" @submit.prevent="submit"><span class="auth-kicker">Recuperacao de acesso</span><h1>{{ token ? 'Definir nova senha' : 'Esqueci minha senha' }}</h1><label v-if="!token" class="field"><span>E-mail</span><input v-model="email" type="email" autocomplete="email" required placeholder="voce@empresa.com"></label><template v-else><label class="field"><span>Nova senha</span><input v-model="password" type="password" autocomplete="new-password" minlength="10" required></label><label class="field"><span>Confirmar senha</span><input v-model="confirmation" type="password" autocomplete="new-password" minlength="10" required></label><p class="auth-hint">Use 10 caracteres, letras maiusculas e minusculas, numero e caractere especial.</p></template><p v-if="message" class="auth-hint">{{ message }}</p><p v-if="error" class="auth-error">{{ error }}</p><button class="btn btn--primary auth-submit" :disabled="loading">{{ loading ? 'Aguarde...' : token ? 'Redefinir senha' : 'Enviar instrucoes' }}</button><NuxtLink class="auth-recovery" to="/login">Voltar para o login</NuxtLink></form></section></main></template>
